CREATE TABLE IF NOT EXISTS aviation_briefing_feedback (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), briefing_id varchar NOT NULL REFERENCES aviation_briefings(id) ON DELETE CASCADE, reader_hash text NOT NULL, user_id varchar REFERENCES users(id) ON DELETE SET NULL, response_type text NOT NULL CHECK (response_type IN ('helpful','learn_more')), created_at timestamp DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS idx_aviation_feedback_reader ON aviation_briefing_feedback(briefing_id, reader_hash); CREATE INDEX IF NOT EXISTS idx_aviation_feedback_briefing ON aviation_briefing_feedback(briefing_id, created_at DESC);
CREATE TABLE IF NOT EXISTS aviation_briefing_saves (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), briefing_id varchar NOT NULL REFERENCES aviation_briefings(id) ON DELETE CASCADE, user_id varchar NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamp DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS idx_aviation_save_user_briefing ON aviation_briefing_saves(user_id, briefing_id); CREATE INDEX IF NOT EXISTS idx_aviation_save_briefing ON aviation_briefing_saves(briefing_id);
CREATE TABLE IF NOT EXISTS aviation_briefing_suggestions (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email varchar NOT NULL, suggested_person text NOT NULL, organization text, topic text NOT NULL, reason text NOT NULL, website text, notes text, status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','reviewing','contacted','completed','closed')), assigned_admin_user_id varchar REFERENCES users(id) ON DELETE SET NULL, source_briefing_id varchar REFERENCES aviation_briefings(id) ON DELETE SET NULL, converted_invitation_id varchar REFERENCES aviation_contributor_invitations(id) ON DELETE SET NULL, created_at timestamp DEFAULT now(), updated_at timestamp DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_aviation_suggestion_status ON aviation_briefing_suggestions(status, created_at DESC); CREATE INDEX IF NOT EXISTS idx_aviation_suggestion_assignee ON aviation_briefing_suggestions(assigned_admin_user_id); CREATE INDEX IF NOT EXISTS idx_aviation_suggestion_email ON aviation_briefing_suggestions(email);
